<script setup lang="ts">definePageMeta({middleware:'auth'});useHead({title:'اعلان‌ها'});const{api}=useShopApi(),unread=useState('notification-unread',()=>0);const{data,refresh}=await useAsyncData('my-notifications',()=>api<any>('/notifications'));watchEffect(()=>unread.value=data.value?.unread||0);async function open(item:any){if(!item.read_at)await api(`/notifications/${item.id}/read`,{method:'PATCH'});if(item.action_url)await navigateTo(item.action_url);else await refresh()}async function all(){await api('/notifications/read-all',{method:'PATCH'});await refresh()}</script>
<template><div class="mx-auto max-w-3xl px-4 py-10"><div class="flex items-center justify-between"><div><p class="text-sm text-slate-400">حساب کاربری</p><h1 class="mt-1 text-2xl font-black">اعلان‌های من</h1></div><button v-if="data?.unread" class="text-sm font-bold text-brand-700" @click="all">خواندن همه</button></div><div class="mt-7 space-y-3"><button v-for="item in data?.notifications?.data" :key="item.id" :class="['block w-full rounded-2xl border p-5 text-right',item.read_at?'bg-white':'border-brand-200 bg-brand-50']" @click="open(item)"><div class="flex justify-between"><b>{{item.title}}</b><span v-if="!item.read_at" class="size-2 rounded-full bg-brand-600"/></div><p class="mt-2 text-sm leading-7 text-slate-600">{{item.message}}</p><p class="mt-2 text-xs text-slate-400">{{new Date(item.created_at).toLocaleString('fa-IR')}}</p></button><div v-if="!data?.notifications?.data?.length" class="rounded-2xl border border-dashed bg-white p-14 text-center text-slate-400">اعلانی برای شما وجود ندارد.</div></div></div></template>
